package com.veyra.notification;import com.veyra.security.CurrentUser;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController{private final JdbcTemplate db;public NotificationController(JdbcTemplate d){db=d;}@GetMapping public List<Map<String,Object>> mine(){return db.queryForList("select n.id,n.event_type,n.channel,n.template_code,n.status,n.data,n.sent_at,n.created_at,sb.id booking_id,sb.pickup_address,sb.dropoff_address,sb.scheduled_at,sb.status booking_status from notifications n left join scheduled_bookings sb on sb.id::text=n.data->>'bookingId' where n.user_id=? order by n.created_at desc limit 100",CurrentUser.id());}}